mapper.sql:
SELECT review_evidence.claim_revision_id, 'CODE_REVIEW' AS source_type, review.id AS source_id, review.created_at AS occurred_at, review_evidence.evidence_role AS review_role, NULL::VARCHAR AS message_role, review.practice_session_id AS review_session_id, review.plan_id, review.phase_index, review.problem_slug, review.version_no, review.total_score, review.passed, NULL::TEXT AS message_excerpt FROM learner_memory_claim_review_evidence review_evidence JOIN learner_memory_claim_revision claim ON claim.id = review_evidence.claim_revision_id JOIN practice_code_review review ON review.id = review_evidence.review_id AND review.user_id = claim.user_id WHERE claim.user_id = #{userId} AND claim.status = 'ACTIVE' AND claim.id IN #{revisionId}
AND claim.id = #{claimRevisionId} UNION ALL SELECT message_evidence.claim_revision_id, 'USER_MESSAGE' AS source_type, message.id AS source_id, message.created_at AS occurred_at, NULL::VARCHAR AS review_role, message_evidence.evidence_role AS message_role, NULL::BIGINT AS review_session_id, NULL::BIGINT AS plan_id, NULL::INTEGER AS phase_index, NULL::VARCHAR AS problem_slug, NULL::INTEGER AS version_no, NULL::NUMERIC AS total_score, NULL::BOOLEAN AS passed, LEFT(message.content, 240) AS message_excerpt FROM learner_memory_claim_message_evidence message_evidence JOIN learner_memory_claim_revision claim ON claim.id = message_evidence.claim_revision_id JOIN agent_message message ON message.id = message_evidence.message_id JOIN agent_task task ON task.id = message.task_id AND task.user_id = claim.user_id WHERE claim.user_id = #{userId} AND claim.status = 'ACTIVE' AND claim.id IN #{revisionId}
AND claim.id = #{claimRevisionId}

mapper.select:
SELECT * FROM () document_evidence

  WHERE occurred_at > #{cursorOccurredAt}
    OR (occurred_at = #{cursorOccurredAt} AND source_type > #{cursorSourceType})
    OR (occurred_at = #{cursorOccurredAt} AND source_type = #{cursorSourceType} AND source_id > #{cursorSourceId})

ORDER BY occurred_at ASC, source_type ASC, source_id ASC
LIMIT #{limit}

SELECT COUNT(*) FROM learner_memory_claim_revision
WHERE user_id = #{userId} AND status = 'ACTIVE' AND entry_kind = #{scope.kind} AND dimension = #{scope.dimension}
AND tag_id IS NULLAND tag_id = #{scope.tagId}

mapper.update:
UPDATE learner_memory_update_run
SET status = #{status}, operation_count = #{operationCount}, tool_call_count = #{toolCallCount}, failure_code = #{failureCode}, completed_at = #{completedAt}
WHERE id = #{updateRunId} AND status = 'RUNNING'
